"""Contract variety, persistent career and a neighborhood side project."""
from pathlib import Path
import json
P=Path(__file__).resolve().parents[1]/'core/src/main/resources/data/life.json'
d=json.loads(P.read_text())
base=d['jobs'][:3]
for j in base:
 j.update(kind='feature',tier=0,xp=1,client={'total':'Тамара · Ложка','discount':'Ася · Плёнка','delivery':'Лев · доставка'}[j['id']],feedback={'total':'Тамара: «Касса больше не обсчитывает гостей. Заглядывай на суп».','discount':'Ася: «Теперь скидка срабатывает ровно на пятистах. Спасибо, что проверил границу».','delivery':'Лев: «Курьеры перестали спорить из-за третьего километра. Так гораздо лучше». '}[j['id']],hint='Проверь не только обычный ввод, но и ноль или точную границу условия.',cost=0,once=False,operationBudget=0)
 if j['id']=='total':j['solutions']=[j['source'],j['source'].replace('*','+'),j['source'].replace('price * count','count * count')];j['initialSources']=[j['source'].replace('price * count','prce * count'),*j['solutions'][1:]];j['patches']=['price * count','price + count','count * count']
 elif j['id']=='discount':j['solutions']=[j['source'],j['source'].replace('>=','>'),'fn discount(sum) { return sum; }'];j['initialSources']=j['solutions'];j['patches']=['sum >= 500','sum > 500','Оставить сумму без скидки']
 else:j['solutions']=[j['source'],j['source'].replace('<=','<'),'fn delivery(distance) { return 100; }'];j['initialSources']=j['solutions'];j['patches']=['distance <= 3','distance < 3','Всегда 100 рублей']
 j['seed']=j['tests'][0]['args']
def make(id,title,kind,brief,params,expr,wrong,pay,mins,tier,client,feedback,labels,budget=0,correct=0,cost=0):
 fn=lambda e:'fn '+id+'('+', '.join(params)+') {\n  return '+e+';\n}'
 solutions=[fn(e) for e in wrong];solutions.insert(correct,fn(expr));assert len(solutions)==3
 j=dict(id=id,title=title,kind=kind,brief=brief,function=id,source=fn(expr),solutions=solutions,initialSources=[fn(wrong[0])]*3,pay=pay,minutes=mins,tier=tier,xp=2 if tier else 1,client=client,feedback=feedback,hint='',cost=cost,once=kind=='project',operationBudget=budget,algorithms=labels,patches=labels,tests=[],seed=[])
 return j
jobs=[]
def add(j,cases,hint):
 j['tests']=[dict(args=a,expected=e) for a,e in cases];j['seed']=cases[0][0];j['hint']=hint;jobs.append(j)
add(make('refund','Баг: лишний возврат','bug','Возврат не может быть больше суммы чека. Верни меньшее из paid и requested.',['paid','requested'],'requested > paid ? paid : requested',['requested','requested < paid ? paid : requested'],1100,120,1,'Тамара · Ложка','Тамара: «Исправление уже на кассе. И ни одного лишнего списания».',['Вернуть всю запрошенную сумму','Ограничить возврат суммой чека','Выбрать большую сумму'],correct=1),[([220,100],100),([220,500],220),([0,50],0)],'В логе: paid=220, requested=500 → ушло 500. Возврат должен ограничиваться чеком.')
add(make('queue','Баг: очередь фотографий','bug','Для пустой очереди ожидание 0. Иначе — 2 минуты на каждый снимок.',['photos'],'photos <= 0 ? 0 : photos * 2',['photos * 2 + 2','photos + 2'],1000,110,1,'Ася · фотолаборатория','Ася: «Пустая очередь больше не обещает вечное ожидание. Первый тестовый отпечаток — тебе».',['Добавить запас в две минуты','Сложить снимки и две минуты','Пусто: 0, иначе photos * 2'],correct=2),[([0],0),([1],2),([12],24)],'Пользователь открыл пустую очередь. Проверь входы 0 и 1 — лишняя задержка видна сразу.')
add(make('booking','Баг: переполненный зал','bug','Бронируем до 20 мест. Верни 1, если taken + requested <= 20; иначе 0.',['taken','requested'],'taken + requested <= 20 ? 1 : 0',['taken <= 20 ? 1 : 0','taken + requested < 20 ? 1 : 0'],1250,140,1,'Ника · репетиционная','Ника: «Наконец-то зал не вмещает сорок человек на бумаге. Теперь можно репетировать».',['Проверить обе величины и границу 20','Проверить только занятые места','Считать полный зал ошибкой']),[([15,5],1),([19,2],0),([0,20],1)],'Лог заявки: taken=19, requested=2 → подтверждено. В условии потеряли размер новой группы.')
add(make('batch','Профиль: пакет фотографий','profile','Стоимость обработки: 8 ₽ за фото. Сохрани результат, сократи вычисление до 1 операции.',['photos'],'photos * 8',['photos + photos + photos + photos + photos + photos + photos + photos','photos * 6'],1450,150,2,'Ася · выставка','Ася: «Пакеты обрабатываются быстрее. У меня осталось время доснять вечерний свет».',['Восемь одинаковых слагаемых','Умножить на 8','Умножить на 6'],budget=1,correct=1),[([0],0),([3],24),([18],144)],'Профилировщик считает реальные арифметические операции. Повторяющиеся слагаемые можно заменить умножением.')
add(make('cache','Профиль: баланс абонемента','profile','Остаток = bought - used. Убери лишнюю арифметику, максимум 1 операция.',['bought','used'],'bought - used',['(bought * 10 - used * 10) / 10','used - bought'],1500,150,2,'Ника · репетиционная','Ника: «Измерение до и после — вот это я уважаю. Патч маленький, эффект понятный».',['Упростить до bought - used','Сохранить умножения и деление','Вычесть купленное из использованного'],budget=1),[([10,3],7),([4,4],0),([20,1],19)],'Результат верный, но умножение обоих чисел на 10 и обратное деление ничего не меняют.')
add(make('fees','Профиль: комиссия','profile','Комиссия равна 5% суммы. Максимум 1 операция без изменения результата.',['sum'],'sum * 0.05',['sum / 100 * 5','sum * 0.5'],1350,135,2,'Лев · доставка','Лев: «Новая версия считает комиссию одним действием. Залил на рабочий терминал».',['Разделить на 100, умножить на 5','Взять половину суммы','Умножить на 0.05'],budget=1,correct=2),[([100],5),([600],30),([0],0)],'Два действия можно объединить. Не перепутай 0.05 с 0.5 — сравни ответ на 100.')
add(make('board','Свой бот · объявления','project','Этап 1/3. Новые объявления живут 7 дней включительно: верни 1 при age <= 7, иначе 0.',['age'],'age <= 7 ? 1 : 0',['age < 7 ? 1 : 0','1'],0,100,0,'Соседи · свой проект','В районном боте появились объявления. Мира первой разместила обмен книгами.',['Публиковать до 7 дней включительно','Убирать уже на седьмой день','Показывать всё навсегда'],cost=300),[([1],1),([7],1),([8],0)],'Это твой продукт. Отсечка в 7 дней должна включать сам седьмой день.')
add(make('remind','Свой бот · напоминания','project','Этап 2/3. Напомни, если до события осталось от 0 до 2 дней включительно. Верни 1 или 0.',['days'],'days < 0 ? 0 : (days <= 2 ? 1 : 0)',['days <= 2 ? 1 : 0','days < 2 ? 1 : 0'],0,120,0,'Соседи · свой проект','Ася добавила в бот даты выставки. Соседям больше не приходится искать сообщение в чате.',['Напоминать обо всём, что <= 2','Проверить сначала прошлое, затем 2 дня','Не напоминать ровно за 2 дня'],correct=1,cost=300),[([-1],0),([0],1),([2],1),([3],0)],'Прошедшее событие — отрицательное число. Одной проверки <= 2 недостаточно.')
add(make('support','Свой бот · запуск','project','Этап 3/3. Поддержка бота: не больше 160 ₽ в день. Верни меньшее из donations и 160.',['donations'],'donations > 160 ? 160 : donations',['donations','160'],0,140,0,'Соседи · свой проект','Районный бот запущен. Поддержка жителей приносит 160 ₽ за следующий игровой день. Это дополнение к работе, а не замена ей.',['Принимать любую сумму','Всегда считать 160','Ограничить сумму сверху: 160'],correct=2,cost=300),[([0],0),([80],80),([500],160)],'Ограничение сверху нельзя превращать в фиксированную плату: на вводе 0 ответ тоже 0.')
d['jobs']=base+jobs
P.write_text(json.dumps(d,ensure_ascii=False,indent=2))
print('0.3: 12 contracts, 3 work modes, 3 side-project stages.')
